  // the parsha of the Shabbos on this date; a Friday date (Friday-night simchas) gives the next day's; any other weekday gives ''
  function parshaOf(iso, lang) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || ''); if (!m) return '';
    var d = Date.UTC(+m[1], +m[2] - 1, +m[3]), wd = new Date(d).getUTCDay();
    if (wd === 5) d += 864e5; else if (wd !== 6) return '';
    var i = Math.round((d - Date.UTC(PARSHA.base[0], PARSHA.base[1], PARSHA.base[2])) / (7 * 864e5));
    if (i < 0 || i >= PARSHA.w.length || PARSHA.w[i] < 0) return '';
    return lang === 'en' || lang === 'short' ? 'Parshas ' + PARSHA.en[PARSHA.w[i]] : 'פרשת ' + PARSHA.he[PARSHA.w[i]];
  }
